/**
 * Procedural emotes (wave, dance, high-five, hug, clap, cheer). Mixamo emote clips need an Adobe
 * login, so poses are generated by aiming bones at target directions every frame, layered over the
 * idle animation. This works on any Mixamo-style rig; real clips can replace these later.
 */
import * as THREE from 'three';
import type { EmoteName } from '../net/types';

export interface EmoteDef {
  label: string;
  icon: string;
  /** Seconds; 0 = loops until the player moves. */
  duration: number;
}

export const EMOTES: Record<EmoteName, EmoteDef> = {
  wave: { label: 'Wave', icon: '👋', duration: 2.6 },
  dance: { label: 'Dance', icon: '🕺', duration: 0 },
  dance2: { label: 'Hands up', icon: '💃', duration: 0 },
  highfive: { label: 'High five', icon: '🙌', duration: 1.8 },
  hug: { label: 'Hug', icon: '🤗', duration: 2.6 },
  clap: { label: 'Clap', icon: '👏', duration: 3 },
  cheer: { label: 'Cheer', icon: '🎉', duration: 2.4 },
};

/** Character space: +z forward, +y up, the character's right side is −x. */
type Vec = [number, number, number];
interface Pose {
  rightArm?: Vec;
  rightForeArm?: Vec;
  leftArm?: Vec;
  leftForeArm?: Vec;
  /** Twist of the upper body about the vertical axis (radians). */
  spineTwist?: number;
  /** Sideways lean of the upper body (radians). */
  spineLean?: number;
  /** Vertical bounce of the whole body (meters). */
  bounce?: number;
}

function poseFor(name: EmoteName, t: number): Pose {
  const s = Math.sin;
  switch (name) {
    case 'wave':
      return { rightArm: [-0.45, 0.85, 0.2], rightForeArm: [-0.15 + 0.35 * s(t * 9), 1, 0.15] };
    case 'cheer': {
      const pump = 0.12 * s(t * 10);
      return {
        rightArm: [-0.3, 0.95, 0.1],
        leftArm: [0.3, 0.95, 0.1],
        rightForeArm: [-0.1, 1, pump],
        leftForeArm: [0.1, 1, pump],
        bounce: 0.04 * Math.abs(s(t * 5)),
      };
    }
    case 'highfive':
      return { rightArm: [-0.25, 0.75, 0.6], rightForeArm: [-0.1, 0.95, 0.35] };
    case 'hug':
      return {
        rightArm: [-0.4, 0.05, 0.95],
        rightForeArm: [0.65, 0.05, 0.75],
        leftArm: [0.4, 0.05, 0.95],
        leftForeArm: [-0.65, 0.05, 0.75],
      };
    case 'clap': {
      const c = 0.28 * s(t * 14);
      return {
        rightArm: [-0.25, -0.15, 0.95],
        leftArm: [0.25, -0.15, 0.95],
        rightForeArm: [0.45 + c, 0.25, 0.85],
        leftForeArm: [-0.45 - c, 0.25, 0.85],
      };
    }
    case 'dance': {
      // ~120 BPM groove: alternate arm pumps, hip twist, bounce on the beat.
      const beat = t * Math.PI * 2;
      return {
        rightArm: [-0.65, 0.2 + 0.45 * s(beat), 0.35],
        leftArm: [0.65, 0.2 - 0.45 * s(beat), 0.35],
        rightForeArm: [-0.2, 0.7 + 0.3 * s(beat), 0.6],
        leftForeArm: [0.2, 0.7 - 0.3 * s(beat), 0.6],
        spineTwist: 0.28 * s(beat / 2),
        bounce: 0.06 * Math.abs(s(beat)),
      };
    }
    case 'dance2': {
      const sway = s(t * Math.PI * 2);
      return {
        rightArm: [-0.25 + 0.25 * sway, 0.95, 0.1],
        leftArm: [0.25 + 0.25 * sway, 0.95, 0.1],
        rightForeArm: [-0.1 + 0.4 * sway, 1, 0],
        leftForeArm: [0.1 + 0.4 * sway, 1, 0],
        spineLean: 0.18 * sway,
        bounce: 0.05 * Math.abs(s(t * Math.PI * 2)),
      };
    }
  }
}

const tmp = {
  a: new THREE.Vector3(),
  b: new THREE.Vector3(),
  d0: new THREE.Vector3(),
  d1: new THREE.Vector3(),
  q: new THREE.Quaternion(),
  qw: new THREE.Quaternion(),
  parent: new THREE.Quaternion(),
  world: new THREE.Quaternion(),
  ident: new THREE.Quaternion(),
};

/** Rotates `bone` (blended by weight) so the segment toward `child` points along `dir`. */
function aim(
  bone: THREE.Object3D,
  child: THREE.Object3D,
  dir: Vec,
  charQuat: THREE.Quaternion,
  w: number,
): void {
  child.updateWorldMatrix(true, false);
  bone.getWorldPosition(tmp.a);
  child.getWorldPosition(tmp.b);
  tmp.d0.subVectors(tmp.b, tmp.a).normalize();
  tmp.d1.set(dir[0], dir[1], dir[2]).normalize().applyQuaternion(charQuat);
  tmp.q.setFromUnitVectors(tmp.d0, tmp.d1);
  tmp.qw.copy(tmp.ident).slerp(tmp.q, w);
  bone.getWorldQuaternion(tmp.world);
  bone.parent?.getWorldQuaternion(tmp.parent);
  bone.quaternion.copy(tmp.parent.invert().multiply(tmp.qw.multiply(tmp.world)));
}

function rotateWorld(bone: THREE.Object3D, axis: THREE.Vector3, angle: number): void {
  bone.updateWorldMatrix(true, false);
  bone.getWorldQuaternion(tmp.world);
  bone.parent?.getWorldQuaternion(tmp.parent);
  tmp.q.setFromAxisAngle(axis, angle);
  bone.quaternion.copy(tmp.parent.invert().multiply(tmp.q.multiply(tmp.world)));
}

/** Blend weight: fades in, holds, and fades out at the end of timed emotes. */
export function emoteWeight(name: EmoteName, t: number): number {
  const d = EMOTES[name].duration;
  const fadeIn = Math.min(1, t / 0.25);
  if (!d) return fadeIn;
  return Math.max(0, Math.min(fadeIn, (d - t) / 0.3));
}

export function emoteFinished(name: EmoteName, t: number): boolean {
  const d = EMOTES[name].duration;
  return d > 0 && t >= d;
}

/**
 * Applies an emote on top of the current (mixer-driven) pose. Call after mixer.update().
 * `facing` is the object whose orientation defines character space (+z forward).
 * Returns the vertical bounce to add to the character.
 */
export function applyEmote(
  skeleton: THREE.Skeleton,
  facing: THREE.Object3D,
  name: EmoteName,
  t: number,
): number {
  const w = emoteWeight(name, t);
  if (w <= 0) return 0;
  const bone = (n: string) => skeleton.getBoneByName(`mixamorig${n}`);
  const pose = poseFor(name, t);
  const charQuat = facing.getWorldQuaternion(new THREE.Quaternion());
  const up = new THREE.Vector3(0, 1, 0);
  const forward = new THREE.Vector3(0, 0, 1).applyQuaternion(charQuat);

  const spine = bone('Spine1');
  if (spine && pose.spineTwist) rotateWorld(spine, up, pose.spineTwist * w);
  if (spine && pose.spineLean) rotateWorld(spine, forward, pose.spineLean * w);
  const pairs: [string, string, Vec | undefined][] = [
    ['RightArm', 'RightForeArm', pose.rightArm],
    ['RightForeArm', 'RightHand', pose.rightForeArm],
    ['LeftArm', 'LeftForeArm', pose.leftArm],
    ['LeftForeArm', 'LeftHand', pose.leftForeArm],
  ];
  for (const [b, c, dir] of pairs) {
    const pb = bone(b);
    const pc = bone(c);
    if (pb && pc && dir) aim(pb, pc, dir, charQuat, w);
  }
  return (pose.bounce ?? 0) * w;
}
